package stm

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"testing"
)

// goldenAggregateCBOR is GOLDEN_CBOR_BYTES (3007 bytes) from
// mithril-stm/src/protocol/aggregate_signature/signature.rs at release
// 2642.0: the to_bytes form of the aggregate signature in
// goldenAggregateJSON.
const goldenAggregateCBOR = ""

func TestGoldenAggregateCBOR(t *testing.T) {
	want, _ := hex.DecodeString(goldenAggregateCBOR)
	var p ConcatenationProof
	if err := json.Unmarshal([]byte(goldenAggregateJSON), &p); err != nil {
		t.Fatal(err)
	}
	if got := p.AggregateSignatureBytes(); !bytes.Equal(got, want) {
		t.Fatalf("%d bytes, want %d\n got %x\nwant %x", len(got), len(want), got, want)
	}
}
